 18	class PodcastController {
 19	  /**
 20	   * POST /api/podcasts
 21	   * Create podcast
 22	   */
 23	  async create(req, res) {
 24	    if (!req.user.isAdminOrUp) {
 25	      Logger.error(`[PodcastController] Non-admin user "${req.user.username}" attempted to create podcast`)
 26	      return res.sendStatus(403)
 27	    }
 28	    const payload = req.body
 29	    if (!payload.media || !payload.media.metadata) {
 30	      return res.status(400).send('Invalid request body. "media" and "media.metadata" are required')
 31	    }
 32	
 33	    if (payload.media.autoDownloadSchedule && !cron.validate(payload.media.autoDownloadSchedule)) {
 34	      Logger.error(`[PodcastController] Invalid auto download schedule cron expression "${payload.media.autoDownloadSchedule}"`)
 35	      return res.status(400).send('Invalid auto download schedule cron expression')
 36	    }
 37	
 38	    const library = await Database.libraryModel.findByIdWithFolders(payload.libraryId)
 39	    if (!library) {
 40	      Logger.error(`[PodcastController] Create: Library not found "${payload.libraryId}"`)
 41	      return res.status(404).send('Library not found')
 42	    }
 43	
 44	    const folder = library.libraryFolders.find((fold) => fold.id === payload.folderId)
 45	    if (!folder) {
 46	      Logger.error(`[PodcastController] Create: Folder not found "${payload.folderId}"`)
 47	      return res.status(404).send('Folder not found')
 48	    }
 49	
 50	    if (typeof payload.path !== 'string' || !payload.path.trim()) {
 51	      return res.status(400).send('Invalid request body. "path" must be a non-empty string')
 52	    }
 53	
 54	    const libraryFolderPath = filePathToPOSIX(folder.path)
 55	    const podcastPath = filePathToPOSIX(payload.path)
 56	
 57	    if (!isSameOrSubPath(libraryFolderPath, podcastPath)) {
 58	      Logger.error(`[PodcastController] Create: Podcast path is outside library folder "${libraryFolderPath}": "${podcastPath}"`)
 59	      return res.status(400).send('Podcast path must be inside the selected library folder')
 60	    }
 61	
 62	    // Check if a library item with this podcast folder exists already
 63	    const existingLibraryItem =
 64	      (await Database.libraryItemModel.count({
 65	        where: {
 66	          path: podcastPath
 67	        }
 68	      })) > 0
 69	    if (existingLibraryItem) {
 70	      Logger.error(`[PodcastController] Podcast already exists at path "${podcastPath}"`)
 71	      return res.status(400).send('Podcast already exists')
 72	    }
 73	
 74	    const success = await fs
 75	      .ensureDir(podcastPath)
 76	      .then(() => true)
 77	      .catch((error) => {
 78	        Logger.error(`[PodcastController] Failed to ensure podcast dir "${podcastPath}"`, error)
 79	        return false
 80	      })
 81	    if (!success) return res.status(400).send('Invalid podcast path')
 82	
 83	    const libraryItemFolderStats = await getFileTimestampsWithIno(podcastPath)
 84	
 85	    let relPath = podcastPath.replace(libraryFolderPath, '')
 86	    if (relPath.startsWith('/')) relPath = relPath.slice(1)
 87	
 88	    let newLibraryItem = null
 89	    const transaction = await Database.sequelize.transaction()
 90	    try {
 91	      const podcast = await Database.podcastModel.createFromRequest(payload.media, transaction)
 92	
 93	      newLibraryItem = await Database.libraryItemModel.create(
 94	        {
 95	          ino: libraryItemFolderStats.ino,
 96	          path: podcastPath,
 97	          relPath,
 98	          mediaId: podcast.id,
 99	          mediaType: 'podcast',
100	          isFile: false,
101	          isMissing: false,
102	          isInvalid: false,
103	          mtime: libraryItemFolderStats.mtimeMs || 0,
104	          ctime: libraryItemFolderStats.ctimeMs || 0,
105	          birthtime: libraryItemFolderStats.birthtimeMs || 0,
106	          size: 0,
107	          libraryFiles: [],
108	          extraData: {},
109	          libraryId: library.id,
110	          libraryFolderId: folder.id,
111	          title: podcast.title,
112	          titleIgnorePrefix: podcast.titleIgnorePrefix
113	        },
114	        { transaction }
115	      )
116	
117	      await transaction.commit()
118	    } catch (error) {
119	      Logger.error(`[PodcastController] Failed to create podcast: ${error}`)
120	      await transaction.rollback()
121	      return res.status(500).send('Failed to create podcast')
122	    }
123	
124	    newLibraryItem.media = await newLibraryItem.getMediaExpanded()
125	
126	    // Download and save cover image
127	    if (typeof payload.media.metadata.imageUrl === 'string' && payload.media.metadata.imageUrl.startsWith('http')) {
128	      // Podcast cover will always go into library item folder
129	      const coverResponse = await CoverManager.downloadCoverFromUrlNew(payload.media.metadata.imageUrl, newLibraryItem.id, newLibraryItem.path, true)
130	      if (coverResponse.error) {
131	        Logger.error(`[PodcastController] Download cover error from "${payload.media.metadata.imageUrl}": ${coverResponse.error}`)
132	      } else if (coverResponse.cover) {
133	        const coverImageFileStats = await getFileTimestampsWithIno(coverResponse.cover)
134	        if (!coverImageFileStats) {
135	          Logger.error(`[PodcastController] Failed to get cover image stats for "${coverResponse.cover}"`)
136	        } else {
137	          // Add libraryFile to libraryItem and coverPath to podcast
138	          const newLibraryFile = {
139	            ino: coverImageFileStats.ino,
140	            fileType: 'image',
141	            addedAt: Date.now(),
142	            updatedAt: Date.now(),
143	            metadata: {
144	              filename: Path.basename(coverResponse.cover),
145	              ext: Path.extname(coverResponse.cover).slice(1),
146	              path: coverResponse.cover,
147	              relPath: Path.basename(coverResponse.cover),
148	              size: coverImageFileStats.size,
149	              mtimeMs: coverImageFileStats.mtimeMs || 0,
150	              ctimeMs: coverImageFileStats.ctimeMs || 0,
151	              birthtimeMs: coverImageFileStats.birthtimeMs || 0
152	            }
153	          }
154	          newLibraryItem.libraryFiles.push(newLibraryFile)
155	          newLibraryItem.changed('libraryFiles', true)
156	          await newLibraryItem.save()
157	
158	          newLibraryItem.media.coverPath = coverResponse.cover
159	          await newLibraryItem.media.save()
160	        }
161	      }
162	    }
163	
164	    SocketAuthority.libraryItemEmitter('item_added', newLibraryItem)
165	
166	    res.json(newLibraryItem.toOldJSONExpanded())
167	
168	    // Turn on podcast auto download cron if not already on
169	    if (newLibraryItem.media.autoDownloadEpisodes) {
170	      this.cronManager.checkUpdatePodcastCron(newLibraryItem)
171	    }
172	  }
