349	  /**
350	   * PATCH: /api/podcasts/:id/episode/:episodeId
351	   */
352	  async updateEpisode(req, res) {
353	    /** @type {import('../models/PodcastEpisode')} */
354	    const episode = req.libraryItem.media.podcastEpisodes.find((ep) => ep.id === req.params.episodeId)
355	    if (!episode) {
356	      return res.status(404).send('Episode not found')
357	    }
358	
359	    const updatePayload = {}
360	    const supportedStringKeys = ['title', 'subtitle', 'description', 'pubDate', 'episode', 'season', 'episodeType']
361	    for (const key in req.body) {
362	      if (supportedStringKeys.includes(key) && typeof req.body[key] === 'string') {
363	        // Sanitize description HTML
364	        if (key === 'description' && req.body[key]) {
365	          const sanitizedDescription = htmlSanitizer.sanitize(req.body[key])
366	          if (sanitizedDescription !== req.body[key]) {
367	            Logger.debug(`[PodcastController] Sanitized description from "${req.body[key]}" to "${sanitizedDescription}"`)
368	            req.body[key] = sanitizedDescription
369	          }
370	        } else if (key === 'subtitle' && req.body[key]) {
371	          const sanitizedSubtitle = htmlSanitizer.sanitize(req.body[key])
372	          if (sanitizedSubtitle !== req.body[key]) {
373	            Logger.debug(`[PodcastController] Sanitized subtitle from "${req.body[key]}" to "${sanitizedSubtitle}"`)
374	            req.body[key] = sanitizedSubtitle
375	          }
376	        }
377	
378	        updatePayload[key] = req.body[key]
379	      } else if (key === 'enclosure') {
380	        const enclosure = req.body.enclosure
381	        if (enclosure === null) {
382	          updatePayload.enclosureURL = null
383	          updatePayload.enclosureSize = null
384	          updatePayload.enclosureType = null
385	        } else if (typeof enclosure === 'object' && typeof enclosure.url === 'string') {
386	          updatePayload.enclosureURL = enclosure.url
387	          updatePayload.enclosureType = typeof enclosure.type === 'string' ? enclosure.type : null
388	          updatePayload.enclosureSize = enclosure.length !== undefined && enclosure.length !== null ? enclosure.length : null
389	        }
390	      } else if (key === 'chapters' && Array.isArray(req.body[key]) && req.body[key].every((ch) => typeof ch === 'object' && ch.title && ch.start)) {
391	        updatePayload[key] = req.body[key]
392	      } else if (key === 'publishedAt' && typeof req.body[key] === 'number') {
393	        updatePayload[key] = req.body[key]
394	      }
395	    }
396	
397	    if (Object.keys(updatePayload).length) {
398	      episode.set(updatePayload)
399	      if (episode.changed()) {
400	        Logger.info(`[PodcastController] Updated episode "${episode.title}" keys`, episode.changed())
401	        await episode.save()
402	
403	        SocketAuthority.libraryItemEmitter('item_updated', req.libraryItem)
404	      } else {
405	        Logger.info(`[PodcastController] No changes to episode "${episode.title}"`)
406	      }
407	    }
408	
409	    res.json(req.libraryItem.toOldJSONExpanded())
410	  }
