431	  async removeEpisode(req, res) {
432	    const episodeId = req.params.episodeId
433	    const hardDelete = req.query.hard === '1'
434	
435	    /** @type {import('../models/PodcastEpisode')} */
436	    const episode = req.libraryItem.media.podcastEpisodes.find((ep) => ep.id === episodeId)
437	    if (!episode) {
438	      Logger.error(`[PodcastController] removeEpisode episode ${episodeId} not found for item ${req.libraryItem.id}`)
439	      return res.sendStatus(404)
440	    }
441	
442	    // Remove it from the podcastEpisodes array
443	    req.libraryItem.media.podcastEpisodes = req.libraryItem.media.podcastEpisodes.filter((ep) => ep.id !== episodeId)
444	
445	    if (hardDelete) {
446	      const audioFile = episode.audioFile
447	      // TODO: this will trigger the watcher. should maybe handle this gracefully
448	      await fs
449	        .remove(audioFile.metadata.path)
450	        .then(() => {
451	          Logger.info(`[PodcastController] Hard deleted episode file at "${audioFile.metadata.path}"`)
452	        })
453	        .catch((error) => {
454	          Logger.error(`[PodcastController] Failed to hard delete episode file at "${audioFile.metadata.path}"`, error)
455	        })
456	    }
457	
458	    // Remove episode from playlists
459	    await Database.playlistModel.removeMediaItemsFromPlaylists([episodeId])
460	
461	    // Remove media progress for this episode
462	    const mediaProgressRemoved = await Database.mediaProgressModel.destroy({
463	      where: {
464	        mediaItemId: episode.id
465	      }
466	    })
467	    if (mediaProgressRemoved) {
468	      Logger.info(`[PodcastController] Removed ${mediaProgressRemoved} media progress for episode ${episode.id}`)
469	    }
470	
471	    // Remove episode
472	    await episode.destroy()
473	
474	    // Remove library file
475	    req.libraryItem.libraryFiles = req.libraryItem.libraryFiles.filter((file) => file.ino !== episode.audioFile.ino)
476	    req.libraryItem.changed('libraryFiles', true)
477	    await req.libraryItem.save()
478	
479	    // update number of episodes
480	    req.libraryItem.media.numEpisodes = req.libraryItem.media.podcastEpisodes.length
481	    await req.libraryItem.media.save()
482	
483	    SocketAuthority.libraryItemEmitter('item_updated', req.libraryItem)
484	    res.json(req.libraryItem.toOldJSON())
485	  }
