487	  async middleware(req, res, next) {
488	    const libraryItem = await Database.libraryItemModel.getExpandedById(req.params.id)
489	    if (!libraryItem?.media) return res.sendStatus(404)
490	
491	    if (!libraryItem.isPodcast) {
492	      return res.sendStatus(500)
493	    }
494	
495	    // Check user can access this library item
496	    if (!req.user.checkCanAccessLibraryItem(libraryItem)) {
497	      return res.sendStatus(403)
498	    }
