   142	  async update(req, res) {
   143	    // Validation
   144	    const reqBody = req.body || {}
   145	    if (reqBody.libraryId || reqBody.userId) {
   146	      // Could allow support for this if needed with additional validation
   147	      return res.status(400).send('Invalid playlist data. Cannot update libraryId or userId')
   148	    }
   149	    if (reqBody.name && typeof reqBody.name !== 'string') {
   150	      return res.status(400).send('Invalid playlist name')
   151	    }
   152	    if (reqBody.description && typeof reqBody.description !== 'string') {
