   199	      // Set an array of mediaItemId
   200	      const newMediaItemIdOrder = []
   201	      for (const item of reqBody.items) {
   202	        const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
   203	        const mediaItemId = item.episodeId || libraryItem.mediaId
   204	        newMediaItemIdOrder.push(mediaItemId)
   205	      }
   206	
   207	      // Sort existing playlist media items into new order
   208	      existingPlaylistMediaItems.sort((a, b) => {
   209	        const aIndex = newMediaItemIdOrder.findIndex((i) => i === a.mediaItemId)
   210	        const bIndex = newMediaItemIdOrder.findIndex((i) => i === b.mediaItemId)
   211	        return aIndex - bIndex
   212	      })
   213	
   214	      // Update order on playlistMediaItem records
   215	      for (const [index, playlistMediaItem] of existingPlaylistMediaItems.entries()) {
   216	        if (playlistMediaItem.order !== index + 1) {
   217	          await playlistMediaItem.update({
   218	            order: index + 1
   219	          })
   220	          wasUpdated = true
   221	        }
   222	      }
   223	    }
   224	
   225	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
   226	
   227	    const jsonExpanded = req.playlist.toOldJSONExpanded()
   228	    if (wasUpdated) {
   229	      SocketAuthority.clientEmitter(req.playlist.userId, 'playlist_updated', jsonExpanded)
   230	    }
   231	    res.json(jsonExpanded)
   232	  }
