    12	   * Create playlist
    13	   */
    14	  async create(req, res) {
    15	    const reqBody = req.body || {}
    16	
    17	    // Validation
    18	    const nameCleaned = htmlSanitizer.stripAllTags(reqBody.name)
    19	    if (!nameCleaned || !reqBody.libraryId) {
    20	      return res.status(400).send('Invalid playlist data')
    21	    }
    22	    if (reqBody.description && typeof reqBody.description !== 'string') {
    23	      return res.status(400).send('Invalid playlist description')
    24	    }
    25	    if (!req.user.checkCanAccessLibrary(reqBody.libraryId)) {
    26	      Logger.warn(`[PlaylistController] User "${req.user.username}" attempted to create playlist in inaccessible library ${reqBody.libraryId}`)
    27	      return res.sendStatus(403)
    28	    }
    29	    const items = reqBody.items || []
    30	    const isPodcast = items.some((i) => i.episodeId)
    31	    const libraryItemIds = new Set()
    32	    for (const item of items) {
    33	      if (!item.libraryItemId || typeof item.libraryItemId !== 'string') {
    34	        return res.status(400).send('Invalid playlist item')
    35	      }
    36	      if (isPodcast && (!item.episodeId || typeof item.episodeId !== 'string')) {
    37	        return res.status(400).send('Invalid playlist item episodeId')
    38	      } else if (!isPodcast && item.episodeId) {
    39	        return res.status(400).send('Invalid playlist item episodeId')
    40	      }
    41	      libraryItemIds.add(item.libraryItemId)
    42	    }
    43	
    44	    // Load library items
    45	    const libraryItems = await Database.libraryItemModel.findAll({
    46	      attributes: ['id', 'mediaId', 'mediaType', 'libraryId'],
    47	      where: {
    48	        id: Array.from(libraryItemIds),
    49	        libraryId: reqBody.libraryId,
    50	        mediaType: isPodcast ? 'podcast' : 'book'
    51	      }
    52	    })
    53	    if (libraryItems.length !== libraryItemIds.size) {
    54	      return res.status(400).send('Invalid playlist data. Invalid items')
    55	    }
    56	
    57	    // Validate podcast episodes
    58	    if (isPodcast) {
    59	      const podcastEpisodeIds = items.map((i) => i.episodeId)
    60	      const podcastEpisodes = await Database.podcastEpisodeModel.findAll({
    61	        attributes: ['id'],
    62	        where: {
    63	          id: podcastEpisodeIds
    64	        }
    65	      })
    66	      if (podcastEpisodes.length !== podcastEpisodeIds.length) {
    67	        return res.status(400).send('Invalid playlist data. Invalid podcast episodes')
    68	      }
    69	    }
    70	
    71	    const transaction = await Database.sequelize.transaction()
    72	    try {
    73	      // Create playlist
    74	      const newPlaylist = await Database.playlistModel.create(
    75	        {
    76	          libraryId: reqBody.libraryId,
    77	          userId: req.user.id,
    78	          name: nameCleaned,
    79	          description: reqBody.description || null
    80	        },
    81	        { transaction }
    82	      )
    83	
    84	      // Create playlistMediaItems
    85	      const playlistItemPayloads = []
    86	      for (const [index, item] of items.entries()) {
    87	        const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
    88	        playlistItemPayloads.push({
    89	          playlistId: newPlaylist.id,
    90	          mediaItemId: item.episodeId || libraryItem.mediaId,
    91	          mediaItemType: item.episodeId ? 'podcastEpisode' : 'book',
    92	          order: index + 1
    93	        })
    94	      }
    95	
    96	      await Database.playlistMediaItemModel.bulkCreate(playlistItemPayloads, { transaction })
    97	
    98	      await transaction.commit()
    99	
   100	      newPlaylist.playlistMediaItems = await newPlaylist.getMediaItemsExpandedWithLibraryItem()
   101	
   102	      const jsonExpanded = newPlaylist.toOldJSONExpanded()
   103	      SocketAuthority.clientEmitter(newPlaylist.userId, 'playlist_added', jsonExpanded)
   104	      res.json(jsonExpanded)
   105	    } catch (error) {
   106	      await transaction.rollback()
   107	      Logger.error('[PlaylistController] create:', error)
   108	      res.status(500).send('Failed to create playlist')
   109	    }
   110	  }
