   136	  /**
   137	   * PATCH: /api/playlists/:id
   138	   * Update playlist
   139	   *
   140	   * Used for updating name and description or reordering items
   141	   */
   142	  async update(req, res) {
   143	    // Validation
   144	    const reqBody = req.body || {}
   145	    if (reqBody.libraryId || reqBody.userId) {
   146	      // Could allow support for this if needed with additional validation
   147	      return res.status(400).send('Invalid playlist data. Cannot update libraryId or userId')
   148	    }
   149	    if (reqBody.name && typeof reqBody.name !== 'string') {
   150	      return res.status(400).send('Invalid playlist name')
   151	    }
   152	    if (reqBody.description && typeof reqBody.description !== 'string') {
   153	      return res.status(400).send('Invalid playlist description')
   154	    }
   155	    if (reqBody.items && (!Array.isArray(reqBody.items) || reqBody.items.some((i) => !i.libraryItemId || typeof i.libraryItemId !== 'string' || (i.episodeId && typeof i.episodeId !== 'string')))) {
   156	      return res.status(400).send('Invalid playlist items')
   157	    }
   158	
   159	    const playlistUpdatePayload = {}
   160	
   161	    const nameCleaned = htmlSanitizer.stripAllTags(reqBody.name)
   162	    if (nameCleaned) {
   163	      playlistUpdatePayload.name = nameCleaned
   164	    }
   165	    if (reqBody.description) playlistUpdatePayload.description = reqBody.description
   166	
   167	    // Update name and description
   168	    let wasUpdated = false
   169	    if (Object.keys(playlistUpdatePayload).length) {
   170	      req.playlist.set(playlistUpdatePayload)
   171	      const changed = req.playlist.changed()
   172	      if (changed?.length) {
   173	        await req.playlist.save()
   174	        Logger.debug(`[PlaylistController] Updated playlist ${req.playlist.id} keys [${changed.join(',')}]`)
   175	        wasUpdated = true
   176	      }
   177	    }
   178	
   179	    // If array of items is set then update order of playlist media items
   180	    if (reqBody.items?.length) {
   181	      const libraryItemIds = Array.from(new Set(reqBody.items.map((i) => i.libraryItemId)))
   182	      const libraryItems = await Database.libraryItemModel.findAll({
   183	        attributes: ['id', 'mediaId', 'mediaType'],
   184	        where: {
   185	          id: libraryItemIds
   186	        }
   187	      })
   188	      if (libraryItems.length !== libraryItemIds.length) {
   189	        return res.status(400).send('Invalid playlist items. Items not found')
   190	      }
   191	      /** @type {import('../models/PlaylistMediaItem')[]} */
   192	      const existingPlaylistMediaItems = await req.playlist.getPlaylistMediaItems({
   193	        order: [['order', 'ASC']]
   194	      })
   195	      if (existingPlaylistMediaItems.length !== reqBody.items.length) {
   196	        return res.status(400).send('Invalid playlist items. Length mismatch')
   197	      }
   198	
   199	      // Set an array of mediaItemId
   200	      const newMediaItemIdOrder = []
   201	      for (const item of reqBody.items) {
   202	        const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
   203	        const mediaItemId = item.episodeId || libraryItem.mediaId
   204	        newMediaItemIdOrder.push(mediaItemId)
   205	      }
   206	
   207	      // Sort existing playlist media items into new order
   208	      existingPlaylistMediaItems.sort((a, b) => {
   209	        const aIndex = newMediaItemIdOrder.findIndex((i) => i === a.mediaItemId)
   210	        const bIndex = newMediaItemIdOrder.findIndex((i) => i === b.mediaItemId)
   211	        return aIndex - bIndex
   212	      })
   213	
   214	      // Update order on playlistMediaItem records
   215	      for (const [index, playlistMediaItem] of existingPlaylistMediaItems.entries()) {
   216	        if (playlistMediaItem.order !== index + 1) {
   217	          await playlistMediaItem.update({
   218	            order: index + 1
   219	          })
   220	          wasUpdated = true
   221	        }
   222	      }
   223	    }
   224	
   225	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
   226	
   227	    const jsonExpanded = req.playlist.toOldJSONExpanded()
   228	    if (wasUpdated) {
   229	      SocketAuthority.clientEmitter(req.playlist.userId, 'playlist_updated', jsonExpanded)
   230	    }
   231	    res.json(jsonExpanded)
   232	  }
