   247	  /**
   248	   * POST: /api/playlists/:id/item
   249	   * Add item to playlist
   250	   *
   251	   * This is not used by Abs web client or mobile apps. Only the batch endpoints are used.
   252	   */
   253	  async addItem(req, res) {
   254	    const itemToAdd = req.body || {}
   255	
   256	    if (!itemToAdd.libraryItemId) {
   257	      return res.status(400).send('Request body has no libraryItemId')
   258	    }
   259	
   260	    const libraryItem = await Database.libraryItemModel.getExpandedById(itemToAdd.libraryItemId)
   261	    if (!libraryItem) {
   262	      return res.status(400).send('Library item not found')
   263	    }
   264	    if (libraryItem.libraryId !== req.playlist.libraryId) {
   265	      return res.status(400).send('Library item in different library')
   266	    }
   267	    if ((itemToAdd.episodeId && !libraryItem.isPodcast) || (libraryItem.isPodcast && !itemToAdd.episodeId)) {
   268	      return res.status(400).send('Invalid item to add for this library type')
   269	    }
   270	    if (itemToAdd.episodeId && !libraryItem.media.podcastEpisodes.some((pe) => pe.id === itemToAdd.episodeId)) {
   271	      return res.status(400).send('Episode not found in library item')
   272	    }
   273	
   274	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
   275	
   276	    if (req.playlist.checkHasMediaItem(itemToAdd.libraryItemId, itemToAdd.episodeId)) {
   277	      return res.status(400).send('Item already in playlist')
   278	    }
   279	
   280	    const jsonExpanded = req.playlist.toOldJSONExpanded()
   281	
   282	    const playlistMediaItem = {
   283	      playlistId: req.playlist.id,
   284	      mediaItemId: itemToAdd.episodeId || libraryItem.media.id,
   285	      mediaItemType: itemToAdd.episodeId ? 'podcastEpisode' : 'book',
   286	      order: req.playlist.playlistMediaItems.length + 1
   287	    }
   288	    await Database.playlistMediaItemModel.create(playlistMediaItem)
   289	
   290	    // Add the new item to to the old json expanded to prevent having to fully reload the playlist media items
   291	    if (itemToAdd.episodeId) {
   292	      const episode = libraryItem.media.podcastEpisodes.find((ep) => ep.id === itemToAdd.episodeId)
   293	      jsonExpanded.items.push({
   294	        episodeId: itemToAdd.episodeId,
   295	        episode: episode.toOldJSONExpanded(libraryItem.id),
   296	        libraryItemId: libraryItem.id,
   297	        libraryItem: libraryItem.toOldJSONMinified()
   298	      })
   299	    } else {
   300	      jsonExpanded.items.push({
   301	        libraryItemId: libraryItem.id,
   302	        libraryItem: libraryItem.toOldJSONExpanded()
   303	      })
   304	    }
   305	
   306	    SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_updated', jsonExpanded)
   307	    res.json(jsonExpanded)
   308	  }
