   310	  /**
   311	   * DELETE: /api/playlists/:id/item/:libraryItemId/:episodeId?
   312	   * Remove item from playlist
   313	   */
   314	  async removeItem(req, res) {
   315	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
   316	
   317	    let playlistMediaItem = null
   318	    if (req.params.episodeId) {
   319	      playlistMediaItem = req.playlist.playlistMediaItems.find((pmi) => pmi.mediaItemId === req.params.episodeId)
   320	    } else {
   321	      playlistMediaItem = req.playlist.playlistMediaItems.find((pmi) => pmi.mediaItem.libraryItem?.id === req.params.libraryItemId)
   322	    }
   323	    if (!playlistMediaItem) {
   324	      return res.status(404).send('Media item not found in playlist')
   325	    }
   326	
   327	    // Remove record
   328	    await playlistMediaItem.destroy()
   329	    req.playlist.playlistMediaItems = req.playlist.playlistMediaItems.filter((pmi) => pmi.id !== playlistMediaItem.id)
   330	
   331	    // Update playlist media items order
   332	    for (const [index, mediaItem] of req.playlist.playlistMediaItems.entries()) {
   333	      if (mediaItem.order !== index + 1) {
   334	        await mediaItem.update({
   335	          order: index + 1
   336	        })
   337	      }
   338	    }
   339	
   340	    const jsonExpanded = req.playlist.toOldJSONExpanded()
   341	
   342	    // Playlist is removed when there are no items
   343	    if (!jsonExpanded.items.length) {
   344	      Logger.info(`[PlaylistController] Playlist "${jsonExpanded.name}" has no more items - removing it`)
   345	      await req.playlist.destroy()
   346	      SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_removed', jsonExpanded)
   347	    } else {
   348	      SocketAuthority.clientEmitter(jsonExpanded.userId, 'playlist_updated', jsonExpanded)
   349	    }
   350	
   351	    res.json(jsonExpanded)
   352	  }
