   354	  /**
   355	   * POST: /api/playlists/:id/batch/add
   356	   * Batch add playlist items
   357	   */
   358	  async addBatch(req, res) {
   359	    if (!req.body.items?.length || !Array.isArray(req.body.items) || req.body.items.some((i) => !i?.libraryItemId || typeof i.libraryItemId !== 'string' || (i.episodeId && typeof i.episodeId !== 'string'))) {
   360	      return res.status(400).send('Invalid request body items')
   361	    }
   362	
   363	    // Find all library items
   364	    const libraryItemIds = new Set(req.body.items.map((i) => i.libraryItemId).filter((i) => i))
   365	
   366	    const libraryItems = await Database.libraryItemModel.findAllExpandedWhere({ id: Array.from(libraryItemIds) })
   367	    if (libraryItems.length !== libraryItemIds.size) {
   368	      return res.status(400).send('Invalid request body items')
   369	    }
   370	
   371	    req.playlist.playlistMediaItems = await req.playlist.getMediaItemsExpandedWithLibraryItem()
   372	
   373	    const mediaItemsToAdd = []
   374	    const jsonExpanded = req.playlist.toOldJSONExpanded()
   375	
   376	    // Setup array of playlistMediaItem records to add
   377	    let order = req.playlist.playlistMediaItems.length + 1
   378	    for (const item of req.body.items) {
   379	      const libraryItem = libraryItems.find((li) => li.id === item.libraryItemId)
   380	
   381	      const mediaItemId = item.episodeId || libraryItem.media.id
   382	      if (req.playlist.playlistMediaItems.some((pmi) => pmi.mediaItemId === mediaItemId)) {
   383	        // Already exists in playlist
   384	        continue
   385	      } else {
   386	        mediaItemsToAdd.push({
   387	          playlistId: req.playlist.id,
   388	          mediaItemId,
   389	          mediaItemType: item.episodeId ? 'podcastEpisode' : 'book',
   390	          order: order++
   391	        })
   392	
   393	        // Add the new item to to the old json expanded to prevent having to fully reload the playlist media items
   394	        if (item.episodeId) {
   395	          const episode = libraryItem.media.podcastEpisodes.find((ep) => ep.id === item.episodeId)
   396	          jsonExpanded.items.push({
   397	            episodeId: item.episodeId,
   398	            episode: episode.toOldJSONExpanded(libraryItem.id),
   399	            libraryItemId: libraryItem.id,
   400	            libraryItem: libraryItem.toOldJSONMinified()
   401	          })
   402	        } else {
   403	          jsonExpanded.items.push({
   404	            libraryItemId: libraryItem.id,
   405	            libraryItem: libraryItem.toOldJSONExpanded()
   406	          })
   407	        }
   408	      }
   409	    }
   410	
   411	    if (mediaItemsToAdd.length) {
   412	      await Database.playlistMediaItemModel.bulkCreate(mediaItemsToAdd)
   413	
   414	      SocketAuthority.clientEmitter(req.playlist.userId, 'playlist_updated', jsonExpanded)
   415	    }
   416	
   417	    res.json(jsonExpanded)
   418	  }
