   465	  /**
   466	   * POST: /api/playlists/collection/:collectionId
   467	   * Create a playlist from a collection
   468	   */
   469	  async createFromCollection(req, res) {
   470	    const collection = await Database.collectionModel.findByPk(req.params.collectionId)
   471	    if (!collection) {
   472	      return res.status(404).send('Collection not found')
   473	    }
   474	    if (!req.user.checkCanAccessLibrary(collection.libraryId)) {
   475	      Logger.warn(`[PlaylistController] User "${req.user.username}" attempted to create playlist from collection ${collection.id} in inaccessible library ${collection.libraryId}`)
   476	      return res.status(404).send('Collection not found')
   477	    }
   478	    // Expand collection to get library items
   479	    const collectionExpanded = await collection.getOldJsonExpanded(req.user)
   480	    if (!collectionExpanded) {
   481	      // This can happen if the user has no access to all items in collection
   482	      return res.status(404).send('Collection not found')
   483	    }
   484	
   485	    // Playlists cannot be empty
   486	    if (!collectionExpanded.books.length) {
   487	      return res.status(400).send('Collection has no books')
   488	    }
   489	
   490	    const transaction = await Database.sequelize.transaction()
   491	    try {
   492	      const playlist = await Database.playlistModel.create(
   493	        {
   494	          userId: req.user.id,
   495	          libraryId: collection.libraryId,
   496	          name: collection.name,
   497	          description: collection.description || null
   498	        },
   499	        { transaction }
   500	      )
   501	
   502	      const mediaItemsToAdd = []
   503	      for (const [index, libraryItem] of collectionExpanded.books.entries()) {
   504	        mediaItemsToAdd.push({
   505	          playlistId: playlist.id,
   506	          mediaItemId: libraryItem.media.id,
   507	          mediaItemType: 'book',
   508	          order: index + 1
   509	        })
   510	      }
   511	      await Database.playlistMediaItemModel.bulkCreate(mediaItemsToAdd, { transaction })
   512	
   513	      await transaction.commit()
   514	
   515	      playlist.playlistMediaItems = await playlist.getMediaItemsExpandedWithLibraryItem()
   516	
   517	      const jsonExpanded = playlist.toOldJSONExpanded()
   518	      SocketAuthority.clientEmitter(playlist.userId, 'playlist_added', jsonExpanded)
   519	      res.json(jsonExpanded)
   520	    } catch (error) {
   521	      await transaction.rollback()
   522	      Logger.error('[PlaylistController] createFromCollection:', error)
   523	      res.status(500).send('Failed to create playlist')
   524	    }
   525	  }
