   527	  async middleware(req, res, next) {
   528	    if (req.params.id) {
   529	      const playlist = await Database.playlistModel.findByPk(req.params.id)
   530	      if (!playlist) {
   531	        return res.status(404).send('Playlist not found')
   532	      }
   533	      if (playlist.userId !== req.user.id) {
   534	        Logger.warn(`[PlaylistController] Playlist ${req.params.id} requested by user ${req.user.id} that is not the owner`)
   535	        return res.sendStatus(403)
   536	      }
   537	      if (!req.user.checkCanAccessLibrary(playlist.libraryId)) {
   538	        Logger.warn(`[PlaylistController] User "${req.user.username}" attempted to access playlist ${playlist.id} in inaccessible library ${playlist.libraryId}`)
   539	        return res.status(404).send('Playlist not found')
   540	      }
   541	      req.playlist = playlist
   542	    }
   543	
